// Normaliza o body recebido do formulário
const body = $input.first().json;

// Suporte a Typeform, Tally e Google Forms
let dados = {};

// Typeform
if (body.form_response && body.form_response.answers) {
  const answers = body.form_response.answers;
  const fields = body.form_response.definition.fields;
  fields.forEach((field, i) => {
    const ans = answers[i];
    dados[field.title] = ans?.text || ans?.choice?.label || ans?.number || '';
  });
}
// Tally
else if (body.data && body.data.fields) {
  body.data.fields.forEach(f => {
    dados[f.label] = f.value;
  });
}
// Google Forms (via Apps Script webhook)
else if (body.responses) {
  body.responses.forEach(r => {
    dados[r.question] = r.answer;
  });
}
// Fallback: usa o body diretamente
else {
  dados = body;
}

return [{ json: { dados_brutos: JSON.stringify(dados, null, 2), raw: dados } }];

const response = $input.first().json;
const content = response.choices[0].message.content;

let briefing;
try {
  briefing = JSON.parse(content);
} catch(e) {
  // Tenta extrair JSON de dentro de markdown
  const match = content.match(/```json([\s\S]*?)```/);
  if (match) {
    briefing = JSON.parse(match[1].trim());
  } else {
    briefing = { erro: 'Falha ao parsear briefing', raw: content };
  }
}

return [{ json: { briefing } }];

