return [{ json: { briefing, copy } }];

const response = $input.first().json;

let content = '';
try {
  content = response.candidates[0].content.parts[0].text;
} catch(e) {
  content = JSON.stringify(response);
}

let imagens;
try {
  imagens = JSON.parse(content);
} catch(e) {
  const match = content.match(/```json([\s\S]*?)```/);
  if (match) {
    imagens = JSON.parse(match[1].trim());
  } else {
    imagens = { erro: 'Falha ao parsear imagens', raw: content };
  }
}

const briefing = $('Parsear Briefing Agente 1').first().json.briefing;
const copy = $('Parsear Copy Agente 2').first().json.copy;

return [{ json: { briefing, copy, imagens } }];

const response = $input.first().json;
const content = response.choices[0].message.content;

let validacao;
try {
  validacao = JSON.parse(content);
} catch(e) {
  const match = content.match(/```json([\s\S]*?)```/);
  if (match) {
    validacao = JSON.parse(match[1].trim());
  } else {
    validacao = { erro: 'Falha ao parsear validação', raw: content, aprovado: false };
  }
}

const briefing = $('Parsear Briefing Agente 1').first().json.briefing;
const copy = $('Parsear Copy Agente 2').first().json.copy;
const imagens = $('Parsear Imagens Agente 3').first().json.imagens;

return [{ json: { briefing, copy, imagens, validacao, aprovado: validacao.aprovado === true } }];
